# Fill color per tile: majority within comp. Demo1 fill=2, odd colors 3 and 1.
def solve(D):
    D=np.array(D); H,W=D.shape
    seen=np.zeros_like(D,bool); comps=[]
    for i in range(H):
        for j in range(W):
            if not seen[i,j]:
                comp=[(i,j)]; q=deque([(i,j)]); seen[i,j]=True
                while q:
                    a,b=q.popleft()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x,y] and D[x,y]!=0:
                                seen[x,y]=True; comp.append((x,y)); q.append((x,y))
                comps.append(comp)
    tiles=[]
    for comp in comps:
        vals={int(D[r,c]) for r,c in comp}
        f=Counter(vals).most_common(1)[0][0]
        tiles.append({'comp':comp,'fill':f,'vals':vals})
    allf=Counter(t['fill'] for t in tiles)
    def paint(cells,v):
        for r,c in cells:
            if 0<=r<H and 0<=c<W and D[r,c]==0: E[r,c]=v
    for a in range(len(tiles)):
        for b in range(a+1,len(tiles)):
            tA,tB=tiles[a],tiles[b]
            ov=tA['vals']&tB['vals']
            v=next(iter(ov-{tA['fill']}|{tB['fill']})) if len(ov&{tA['fill'],tB['fill']})==0 else None
            if v is None or v in {tA['fill'],tB['fill']}: continue
            rs=[r for r,c in tA['comp']]; cs=[c for r,c in tA['comp']]
            r4=[r for r,c in tB['comp']]; c4=[c for r,c in tB['comp']]
            if min(rs)==min(r4) and max(rs)==max(r4):
                lo,hi=min(min(cs),min(c4)),max(max(cs),max(c4))
                paint([(min(rs),c) for c in range(lo+1,hi)],v)
            elif min(cs)==min(c4) and max(cs)==max(c4):
                lo,hi=min(min(rs),min(r4)),max(max(rs),max(r4))
                paint([(r,min(cs)) for r in range(lo+1,hi)],v)
    return E.tolist()
for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    got=solve(G[k+' input']); exp=G[k+' output']
    g=np.array(got); e=np.array(exp)
    dd=[(i,j,int(g[i,j]),int(e[i,j])) for i in range(len(g)) for j in range(len(g[0])) if g[i,j]!=e[i,j]]
    print(k,'n',len(dd),dd[:15])
